from pathlib import Path
from textual.app import App, ComposeResult, on
from textual.containers import Horizontal
from textual.widgets import Tree, TextArea, Footer


class FileExplorer(App):
    BINDINGS = [("q", "quit", "Quit")]
    CSS = """
    Screen {
        layout: vertical;
    }

    #main-container {
        height: 1fr;
    }

    #tree-panel {
        width: 30%;
        border: solid $accent;
    }

    #text-panel {
        width: 1fr;
        border: solid $accent;
    }
    """

    def compose(self) -> ComposeResult:
        with Horizontal(id="main-container"):
            yield Tree(".", id="tree-panel")
            yield TextArea(id="text-panel")
        yield Footer()

    def on_mount(self) -> None:
        tree = self.query_one(Tree)
        self._populate_tree(tree.root, Path("."))

    def _populate_tree(self, node: Tree.NodeType, path: Path) -> None:
        try:
            items = sorted(path.iterdir())
        except (PermissionError, OSError):
            return

        for item in items:
            if item.name.startswith("."):
                continue

            if item.is_dir():
                child = node.add(f"📁 {item.name}")
                self._populate_tree(child, item)
            else:
                node.add(f"📄 {item.name}")

    @on(Tree.NodeSelected)
    def _on_node_selected(self, event: Tree.NodeSelected) -> None:
        label = event.node.label.text
        if label.startswith("📄"):
            path = self._get_file_path(event.node)
            if path and path.is_file():
                try:
                    content = path.read_text()
                    self.query_one(TextArea).text = content
                except (PermissionError, UnicodeDecodeError, OSError):
                    self.query_one(TextArea).text = "Error reading file"

    def _get_file_path(self, node: Tree.NodeType) -> Path | None:
        parts = []
        current = node
        while current.parent is not None:
            label = current.label.text.lstrip("📁 📄 ")
            parts.append(label)
            current = current.parent

        if parts:
            return Path(".") / Path(*reversed(parts))
        return None


if __name__ == "__main__":
    FileExplorer().run()

